package de.westnordost.streetcomplete.quests.railway_crossing

import de.westnordost.streetcomplete.data.elementfilter.toElementFilterExpression
import de.westnordost.streetcomplete.data.osm.mapdata.Element
import de.westnordost.streetcomplete.data.osm.mapdata.MapDataWithGeometry
import openquests.candidates
import openquests.custom.AreaQuest

object AddRailwayCrossingBarrier : AreaQuest {
    override val name = "AddRailwayCrossingBarrier"
    override val usesAge = true

    private val crossingFilter by lazy { """
        nodes with
          railway ~ level_crossing|crossing
          and (
            !crossing:barrier and !crossing:chicane
            or crossing:barrier older today -8 years
          )
    """.toElementFilterExpression() }

    private val excludedWaysFilter by lazy { """
        ways with
          highway and access ~ private|no
          or abandoned:railway
          or railway ~ tram|abandoned|disused
          or railway and embedded = yes
    """.toElementFilterExpression() }

    override fun getApplicableElements(mapData: MapDataWithGeometry): Iterable<Element> {
        val excludedWayNodeIds = mapData.candidates(mapData.ways, excludedWaysFilter)
            .filter { excludedWaysFilter.matches(it) }
            .flatMapTo(HashSet()) { it.nodeIds }

        return mapData.candidates(mapData.nodes, crossingFilter)
            .filter { crossingFilter.matches(it) && it.id !in excludedWayNodeIds }
    }
}
